let state = [];
let isInternalUpdate = false;
window.appsmith.onReady(() => {
  window.appsmith.onModelChange(model => {
    if (!model || !model.list || !Array.isArray(model.list)) return;

    // Wenn das Update von einer lokalen Aktion stammt, ignorieren (verhindert Echo-Resets)
    if (isInternalUpdate) {
      return;
    }

    // Externes Update (z.B. durch selectExamSet / Preset-Auswahl)
    const newJson = JSON.stringify(model.list);
    const currentJson = JSON.stringify(state);
    if (newJson !== currentJson) {
      state = JSON.parse(newJson);
      renderApp();
    }
  });
});
function renderApp() {
  const container = document.getElementById("app");
  container.innerHTML = "";
  state.forEach((item, index) => {
    const wrapper = document.createElement("div");
    wrapper.className = "row-item";

    // 1. Checkbox & Label
    const label = document.createElement("label");
    label.className = "checkbox-label";
    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.checked = !!item.checked;
    checkbox.onchange = e => {
      state[index].checked = e.target.checked;
      if (!e.target.checked) {
        state[index].value = "";
      }

      // Entsprechendes Input-Feld direkt im DOM anpassen
      const inputEl = document.getElementById(`input-${index}`);
      if (inputEl) {
        inputEl.disabled = !e.target.checked;
        if (!e.target.checked) inputEl.value = "";
      }
      syncToAppsmith();
    };
    const span = document.createElement("span");
    span.innerText = item.label;
    label.appendChild(checkbox);
    label.appendChild(span);
    wrapper.appendChild(label);

    // 2. Input-Feld
    const input = document.createElement("input");
    input.type = "number";
    input.className = "text-input";
    input.id = `input-${index}`;
    input.placeholder = "0";
    input.value = item.value !== undefined && item.value !== null ? item.value : "";
    input.disabled = !item.checked;
    input.oninput = e => {
      state[index].value = e.target.value === "" ? "" : Number(e.target.value);
    };
    input.onblur = () => {
      syncToAppsmith();
    };
    wrapper.appendChild(input);
    container.appendChild(wrapper);
  });
}
function syncToAppsmith() {
  isInternalUpdate = true;
  const payload = state.map(item => ({
    ...item
  }));
  appsmith.updateModel({
    list: payload
  });
  appsmith.triggerEvent("onSelectionChange");

  // Interne Sperre nach kurzer Zeit wieder aufheben
  setTimeout(() => {
    isInternalUpdate = false;
  }, 300);
}

